mapper.select:
select wrd.*, wr.id rid, wr.serial_number rSN, wr.applicant_name raName, wr.reviewer_name rrName, wr.review_time rrTime, wr.return_time , wr.create_time rcTime, wr.outbound_type_selection wrType, wo.id woId, wo.serial_number sn, wo.applicant_name founderName, wo.reviewer_name reviewerName, wo.create_time createTime, wo.review_time reviewTime, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, mbf.id mbfId, mbf.name mbfName, ww.id wwId, ww.name wwName from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id left join wms_outbound wo on wo.id = wrd.outbound_id left join contract_project p on p.id = wrd.project_id left join wms_workshop mbf on wrd.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wrd.warehouse_id where wrd.bool_delete_enum = 0 and wr.review_status = 2
and wrd.basic_class = #{basicClass}
AND wrd.material_is_whole = #{materialIsWhole}
and wrd.bool_party_a = 1
and wrd.bool_party_a = 0
and wrd.workshop_id = #{workshopId}
AND wrd.warehouse_id = #{warehouseId}
and wr.review_time > #{reviewTime[0]}
and wr.review_time < #{reviewTime[1]}
and wrd.real_time > #{realTime[0]}
and wrd.real_time < #{realTime[1]}
and wr.serial_number like CONCAT('%', #{outboundSN},'%')
and (wr.applicant_name like CONCAT('%', #{operatorName},'%') or wr.reviewer_name like CONCAT('%', #{operatorName},'%'))
and wrd.classify_id in
#{item}
and wrd.project_id is null
and wrd.project_id IS NOT NULL
AND wrd.project_id = #{projectId}
and wrd.width = #{width}
and wrd.length = #{length}
-- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
and wrd.quantity >= #{minLength}
and wrd.quantity <= #{maxLength}
and wrd.theory_thickness = #{theoryThickness}
and wrd.thickness = #{thickness}
and wrd.color like CONCAT('%', #{color},'%')
and wrd.specification like CONCAT('%', #{specification},'%')
and wrd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
AND wrd.brand like CONCAT('%',#{brand},'%')
and wr.outbound_type_selection = #{outboundTypeSelection}
and wrd.workshop_id in
#{item}

        select
        wrd.*,
        wm.*,
        wr.serial_number woSN,
        wr.review_time reviewTime,
        p.name pn,
        p.serial_number psn,
        wo.serial_number wsn,
        wc.name classifyName
        from wms_return_detail wrd
        left join wms_return wr on wr.id = wrd.return_id
        left join contract_project p on p.id = wrd.project_id
        left join wms_classification wc on wrd.classify_id = wc.id
        left join wms_measure wm on wm.classification_id = wrd.classify_id
        left join wms_outbound wo on wo.id=wrd.outbound_id
        where
        wrd.bool_delete_enum = 0
        and wr.review_status = 2
        
            and wrd.basic_class = #{basicClass}
        
        
            AND wrd.material_is_whole = #{materialIsWhole}
        
        
            and wrd.bool_party_a = 1
        
        
            and wrd.bool_party_a = 0
        
        
            and wrd.workshop_id = #{workshopId}
        
        
            AND wrd.warehouse_id = #{warehouseId}
        
        
            
                and wr.review_time > #{reviewTime[0]}
            
            
                and wr.review_time < #{reviewTime[1]}
            
        
        
            
                and wrd.real_time > #{realTime[0]}
            
            
                and wrd.real_time < #{realTime[1]}
            
        
        
            and wr.serial_number like CONCAT('%', #{outboundSN},'%')
        
        
            and (wr.applicant_name like CONCAT('%', #{operatorName},'%')
            or wr.reviewer_name like CONCAT('%', #{operatorName},'%'))
        
        
            and wrd.classify_id in
            
                #{item}
            
        



        
            and wrd.project_id is null
        
        
            and wrd.project_id IS NOT NULL
        
        
            AND wrd.project_id = #{projectId}
        
        
            and wrd.width = #{width}
        
        
            and wrd.length = #{length}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and wrd.quantity >= #{minLength}
        
        
            and wrd.quantity <= #{maxLength}
        
        
            and wrd.theory_thickness = #{theoryThickness}
        
        
            and wrd.thickness = #{thickness}
        
        
            and wrd.color like CONCAT('%', #{color},'%')
        
        
            and wrd.specification like CONCAT('%', #{specification},'%')
        
        
            and wrd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND wrd.brand like CONCAT('%',#{brand},'%')
        
        
            and wrd.workshop_id in
            
                #{item}
            
        
        order by wrd.id desc

select ifnull(sum(wrd.amount),0) from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id where wrd.bool_delete_enum = 0 and wr.review_status = 2 and wrd.classify_id in
#{item}
and DATE_FORMAT(#{localDate}, '%Y%m') = DATE_FORMAT(wr.review_time, '%Y%m')

select ifnull(sum(wrd.mete), 0)
from wms_return_detail wrd
         left join wms_return wr on wr.id = wrd.return_id
where wrd.bool_delete_enum = 0
  and wr.review_status = 2
  and DATE_FORMAT(wrd.create_time, '%m') = #{month}
  and DATE_FORMAT(wrd.create_time, '%y') = #{year}
  and wrd.project_id = #{projectId}

select a.* from wms_return_detail a left join wms_return b on a.return_id = b.id where a.bool_delete_enum = 0 and b.review_status = 2 and b.bool_delete_enum = 0 and b.review_time > #{times.startTime} and b.review_time < #{times.endTime}
AND a.material_returnable_id = #{materialReturnableId}
and a.project_id is null and a.classify_id in
#{item}

select a.* from wms_return_detail a left join wms_return b on a.return_id = b.id where a.bool_delete_enum = 0 and b.review_status = 2 and b.bool_delete_enum = 0 and a.real_time > #{times.startTime} and a.real_time < #{times.endTime}
AND a.material_returnable_id = #{materialReturnableId}
and a.project_id is null and a.classify_id in
#{item}

SELECT wrd.*, wmr.outbound_detail_id outboundDetailId FROM wms_material_returnable wmr LEFT JOIN wms_return_detail wrd ON wmr.id = wrd.material_returnable_id LEFT JOIN wms_return wr ON wr.id = wrd.return_id WHERE wmr.outbound_detail_id in
#{id}
and wrd.bool_delete_enum = 0 AND wr.review_status = 2

SELECT a.*, wm.measure_unit measureUnit, wm.measure_precision measurePrecision, wm.accounting_unit accountingUnit, wm.accounting_precision accountingPrecision FROM wms_return_detail a left join wms_return b on a.return_id = b.id left join wms_measure wm on wm.classification_id = a.classify_id where a.bool_delete_enum = 0 and b.review_status = 2 and b.bool_delete_enum = 0
and a.basic_class & #{basicClass} > 0
and a.project_id = #{projectId}
and b.review_time >= #{startDate}
and b.review_time <= #{endDate}

SELECT wod.id id, wod.project_id, wo.applicant_name, mete, wod.create_time create_time , wod.basic_class basic_class, wod.classify_id classify_id, wod.specification specification, wod.quantity quantity FROM wms_return_detail wod LEFT JOIN wms_return wo ON wod.return_id = wo.id where wo.review_status=2 AND wod.bool_delete_enum=0
and wod.basic_class=#{basicClass}
and wod.project_id in
#{id}
and wod.workshop_id in
#{id}
and wod.project_id IS NOT NULL
AND DATE_FORMAT(wo.review_time, '%Y') = #{year}
and wo.review_time > #{times[0]}
and wo.review_time < #{times[1]}

        select
        sum(wrd.quantity) as quantityCount,
        sum(wrd.mete) as meteCount,
        sum(wrd.amount) as amountCount,
        sum(wrd.amount_excluding_VAT) as amountExcludingVatCount
        from wms_return_detail wrd
        left join wms_return wr on wr.id = wrd.return_id
        left join wms_outbound wo on wo.id = wrd.outbound_id
        left join contract_project p on p.id = wrd.project_id
        left join wms_warehouse ww on ww.id = wrd.warehouse_id
        where
        wrd.bool_delete_enum = 0
        and wr.review_status = 2
        
            and wrd.basic_class = #{basicClass}
        
        
            AND wrd.material_is_whole = #{materialIsWhole}
        
        
            and wrd.bool_party_a = 1
        
        
            and wrd.bool_party_a = 0
        
        
            AND wrd.warehouse_id = #{warehouseId}
        
        
            
                and wr.review_time > #{returnTime[0]}
            
            
                and wr.review_time < #{returnTime[1]}
            
        
        
            and wr.serial_number like CONCAT('%', #{outboundSN},'%')
        
        
            and (wr.applicant_name like CONCAT('%', #{operatorName},'%')
            or wr.reviewer_name like CONCAT('%', #{operatorName},'%'))
        
        
            and wrd.classify_id in
            
                #{item}
            
        
        
            and wrd.classify_id = #{classifyId}
        
        
            and wrd.project_id is null
        
        
            and wrd.project_id IS NOT NULL
        
        
            AND wrd.project_id = #{projectId}
        
        
            and wrd.width = #{width}
        
        
            and wrd.length = #{length}
        
        -- 长度范围只用于钢卷查询,钢卷quantity计量量记录长度
        
            and wrd.quantity >= #{minLength}
        
        
            and wrd.quantity <= #{maxLength}
        
        
            and wrd.theory_thickness = #{theoryThickness}
        
        
            and wrd.thickness = #{thickness}
        
        
            and wrd.color like CONCAT('%', #{color},'%')
        
        
            and wrd.specification like CONCAT('%', #{specification},'%')
        
        
            and wrd.heat_no_and_batch_no like CONCAT('%', #{heatNoAndBatchNo},'%')
        
        
            AND wrd.brand like CONCAT('%',#{brand},'%')
        
        
            and wr.outbound_type_selection = #{outboundTypeSelection}
        
        
            and wrd.workshop_id in
            
                #{item}

select wrd.*, wr.return_time returnTime, wc.id classifyId, wc.name classifyName from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id left join wms_classification wc on wc.id = wrd.classify_id where wrd.bool_delete_enum = 0 and wr.review_status = 2 and wr.outbound_type_selection in (1,128)
and wrd.basic_class = #{basicClass}
and wrd.basic_class in (1,2)
and wrd.thickness = #{thickness}
and wrd.specification = #{material}
and (wrd.specification = #{specification} or wrd.specification = #{prefixSpecification})
and wrd.project_id = #{projectId}
and wrd.workshop_id = #{workShopId}

select wrd.basic_class basicClass, wrd.thickness thickness, wrd.specification specification, sum(wrd.mete) meteCount from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id where wrd.bool_delete_enum = 0 and wr.review_status = 2 and wr.outbound_type_selection in (1,128) and wrd.basic_class = 1
and wrd.project_id = #{projectId}
and wrd.workshop_id = #{workShopId}
group by wrd.basic_class,wrd.thickness,wrd.specification

select wrd.basic_class basicClass, wrd.specification specification, sum(wrd.mete) meteCount from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id where wrd.bool_delete_enum = 0 and wr.review_status = 2 and wr.outbound_type_selection in (1,128) and wrd.basic_class = 2
and wrd.project_id = #{projectId}
and wrd.workshop_id = #{workShopId}
group by wrd.basic_class,wrd.specification

select wrd.project_id as projectId, wrd.basic_class as basicClass, SUM(wrd.mete) as mete, SUM(wrd.amount) as amount, SUM(wrd.amount_excluding_vat) as amount_excluding_vat, DATE_FORMAT(wr.review_time, '%Y-%m') as time from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id and wr.bool_delete_enum = 0 where wrd.bool_delete_enum = 0
and wr.review_status = #{reviewStatus}
and wrd.basic_class in
#{basicClass}
and
DATE_FORMAT(wr.review_time, '%Y-%m') = #{yearMonthStr}
and wrd.project_id in
#{projectId}
and wrd.project_id is null
and wrd.classify_id not in
#{classifyId}
and wrd.classify_id in
#{classifyId}
group by wrd.project_id,wrd.basic_class,DATE_FORMAT(wr.review_time, '%Y-%m')

select DATE_FORMAT(wr.review_time, '%Y-%m') as yearMonth, '退库' as type, wc.basic_class as basicClass, wc.id as classifyId, wc.name as classifyName, wrd.length as length, wrd.width as width, wrd.thickness as thickness, wrd.specification as specification, wrd.brand as brand, wm.measure_unit as measureUnit, SUM(wrd.quantity) as quantityCount, wm.accounting_unit as accountingUnit, SUM(wrd.mete) as meteCount, SUM( wrd.unit_price ) / count(1) AS unitPrice, SUM( wrd.unit_price_excluding_vat ) / count(1) AS unitPriceExcludingVAT, SUM( wrd.amount ) as amountCount, SUM( wrd.amount_excluding_VAT ) as amountExcludingVatCount, wr.serial_number as serialNumber, mbw.id as workshopId, mbw.name workshopName from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id and wr.bool_delete_enum = 0 left join wms_measure wm on wm.classification_id = wrd.classify_id left join mes_building_workshop mbw on mbw.id = wrd.workshop_id left join wms_classification wc on wrd.classify_id = wc.id where wrd.bool_delete_enum = 0
and wr.review_status = #{reviewStatus}
and wrd.basic_class in
#{basicClass}
and wrd.project_id = #{projectId}
and wrd.project_id is null
and
DATE_FORMAT(wr.review_time, '%Y-%m') = #{yearMonthStr}
and wrd.classify_id not in
#{classifyId}
and wrd.classify_id in
#{classifyId}
group by DATE_FORMAT(wr.review_time, '%Y-%m'), wc.basic_class, wc.id, wrd.specification, wrd.length, wrd.width, wrd.thickness, wm.measure_unit, wrd.brand, wm.accounting_unit, wr.serial_number, wm.measure_unit, mbw.id

select * from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id and wr.bool_delete_enum = 0 where wrd.bool_delete_enum = 0 and wrd.project_id is not null and wrd.basic_class in (1,2,4,256) and wr.review_status = 2
and DATE_FORMAT(wr.review_time, '%Y') = #{time}
and wrd.workshop_id = #{workshopId}
and DATE_FORMAT(wr.review_time, '%Y-%m') = #{timeOne}

SELECT 3 AS lossWorkProgressStatisticsEnum, ym_t.`year_month`, IFNULL(ROUND(wrd_t.productMonthOutput,3),0) AS productMonthOutput FROM (
select DATE_FORMAT(#{i}, '%Y-%m') as `year_month`
) ym_t LEFT JOIN ( SELECT DATE_FORMAT( wrd.create_time, '%Y-%m' ) AS `year_month`, IFNULL( SUM( wrd.mete ), 0) / 1000000 as productMonthOutput FROM wms_return_detail AS wrd LEFT JOIN wms_return AS wr ON wrd.return_id = wr.id AND wr.bool_delete_enum = 0 LEFT JOIN wms_outbound wo ON wrd.outbound_id = wo.id AND wo.bool_delete_enum = 0 LEFT JOIN wms_material_returnable wmr ON wrd.material_returnable_id = wmr.id AND wmr.bool_delete_enum = 0 WHERE wrd.bool_delete_enum = 0 AND wr.review_status = 2 AND wo.outbound_type_selection = 1 AND wrd.basic_class & 263 > 0
and wrd.project_id = #{projectId}
and wmr.workshop_id = #{workShopId}
AND date_format(wrd.create_time, '%Y-%m') >= #{minYearMonth}
AND date_format(wrd.create_time, '%Y-%m') <= #{maxYearMonth}
GROUP BY DATE_FORMAT( wrd.create_time, '%Y-%m' ) ) wrd_t ON ym_t.`year_month` = wrd_t.`year_month`

select wrd.*, wr.id rid, wr.serial_number rSN, wr.applicant_name raName, wr.reviewer_name rrName, wr.review_time rrTime, wr.return_time , wr.create_time rcTime, wr.outbound_type_selection wrType, wo.id woId, wo.serial_number sn, wo.applicant_name founderName, wo.reviewer_name reviewerName, wo.create_time createTime, wo.review_time reviewTime, p.id pid, p.short_name psName, p.serial_number pSN, p.name pn, mbw.id mbfId, mbw.name mbfName, ww.id wwId, ww.name wwName from wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id left join wms_outbound wo on wo.id = wrd.outbound_id left join contract_project p on p.id = wrd.project_id left join wms_workshop mbf on wrd.workshop_id = mbf.id left join wms_warehouse ww on ww.id = wrd.warehouse_id LEFT JOIN wms_material_returnable wmr ON wrd.material_returnable_id = wmr.id LEFT JOIN wms_classification wcf ON wrd.classify_id = wcf.id LEFT JOIN mes_building_workshop mbw on wmr.workshop_id = mbw.id WHERE wrd.bool_delete_enum = 0 AND wr.review_status = 2 AND wo.outbound_type_selection = 1 AND wrd.basic_class & 263 > 0
and wrd.basic_class = #{basicClass}
and wrd.project_id = #{projectId}
and wmr.workshop_id = #{workShopId}
AND date_format(wrd.create_time, '%Y-%m-%d') >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND date_format(wrd.create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
and wcf.name like CONCAT('%', #{classifyName},'%')

SELECT wrd.* FROM wms_return_detail wrd left join wms_return wr on wr.id = wrd.return_id and wr.bool_delete_enum = 0 WHERE wrd.bool_delete_enum = 0 AND wr.review_status = 2
AND wrd.basic_class & #{basicClass} > 0
AND wrd.classify_id = #{classifyId}
AND DATE_FORMAT(wrd.create_time, "%Y") = DATE_FORMAT(#{yearDate}, "%Y")
AND DATE_FORMAT(wrd.create_time, "%Y-%m") = DATE_FORMAT(#{mouthDate}, "%Y-%m")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = wrd.project_id )
AND wrd.workshop_id = #{workshopId}
AND wrd.project_id = #{projectId}
order by wrd.create_time desc

SELECT DATE_FORMAT( wrd.create_time, '%Y-%m' ) AS `year_month`, IFNULL( SUM( wrd.mete ), 0) / 1000 as productMonthOutput FROM wms_return_detail AS wrd LEFT JOIN wms_return AS wr ON wrd.return_id = wr.id AND wr.bool_delete_enum = 0 LEFT JOIN wms_outbound wo ON wrd.outbound_id = wo.id AND wo.bool_delete_enum = 0 LEFT JOIN wms_material_returnable wmr ON wrd.material_returnable_id = wmr.id AND wmr.bool_delete_enum = 0 WHERE wrd.bool_delete_enum = 0 AND wr.review_status = 2 AND wo.outbound_type_selection = 1 AND wrd.basic_class & 263 > 0
and wrd.project_id = #{projectId}
GROUP BY DATE_FORMAT( wrd.create_time, '%Y-%m' )

SELECT
    wrd.*,
    wr.review_time reviewTime
FROM
    wms_return_detail AS wrd
    LEFT JOIN wms_return AS wr ON wr.id = wrd.return_id and wr.bool_delete_enum = 0 and wr.review_status = 2
WHERE wrd.bool_delete_enum = 0

    AND wrd.workshop_id = #{workshopId}


    and wr.review_time >= #{startDay}


    and wr.review_time <= #{endDay}
